Matching Ayahs
- = Alif, Laam, Miim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Mereka itulah yang berada di atas petunjuk daripada Tuhan mereka, dan mereka itulah orang-orang yang berjaya. 2:5; 31:5
- = Wahai Bani Israil, ingatlah nikmat-Ku yang telah Aku kurniakan kepadamu dan bahawa Aku telah melebihkan kamu di atas seluruh umat (manusia). 2:47; 2:122
- = Itulah satu umat yang telah lalu. Baginya apa yang telah diusahakannya, dan bagi kamu apa yang kamu usahakan. Dan kamu tidak akan ditanya tentang apa yang mereka kerjakan. 2:134; 2:141
- = Kekal mereka di dalamnya. Azab tidak akan diringankan daripada mereka, dan mereka tidak diberi tangguh. 2:162; 3:88
- = Kecuali orang-orang yang bertaubat sesudah itu dan memperbaiki diri. Maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang. 3:89; 24:5
- = Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni Neraka. 5:10; 5:86
- = Dan tidak ada suatu tanda pun dari tanda-tanda (kekuasaan) Tuhan mereka datang kepada mereka, melainkan mereka selalu berpaling darinya. 6:4; 36:46
- = Dan sesungguhnya telah diperolok-olokkan beberapa rasul sebelum kamu, maka turunlah kepada orang-orang yang mencemohkan di antara mereka azab (balasan) olok-olokan yang mereka perolok-olokkan. 6:10; 21:41
- = Katakanlah: "Sesungguhnya aku takut akan azab hari yang besar jika aku mendurhakai Tuhanku." 6:15; 39:13
- = Maka gempa bumi menimpa mereka, lalu mereka mati bergelimpangan di dalam rumah-rumah mereka. 7:78; 7:91
- = Lalu dia (Musa) melemparkan tongkatnya, maka tiba-tiba ia menjadi ular yang nyata. 7:107; 26:32
- = Dan dia mengeluarkan tangannya, maka tiba-tiba ia menjadi putih (bercahaya) bagi orang-orang yang melihatnya. 7:108; 26:33
- = Mereka berkata: "Kami telah beriman kepada Tuhan sekalian alam." 7:121; 26:47
- = Tuhan Musa dan Harun. 7:122; 26:48
- = Dan Aku akan memberi tangguh kepada mereka. Sesungguhnya rancangan-Ku sangat kuat. 7:183; 68:45
- = Dialah yang mengutus Rasul-Nya dengan petunjuk dan agama yang benar, agar dimenangkan-Nya atas semua agama, walaupun orang-orang musyrik membencinya. 9:33; 61:9
- = Wahai Nabi, berjihadlah melawan orang-orang kafir dan orang-orang munafik, dan bersikap keraslah terhadap mereka. Tempat mereka ialah Neraka Jahannam, dan itulah seburuk-buruk tempat kembali. 9:73; 66:9
- = Dan mereka berkata: "Bilakah janji ini (akan berlaku), jika kamu orang-orang yang benar?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Dan sesungguhnya Kami telah mengutus Musa dengan bukti-bukti Kami dan dengan kekuasaan yang jelas. 11:96; 40:23
- = Dan sesungguhnya Kami telah memberikan Kitab (Taurat) kepada Musa, lalu diperselisihkan tentang Kitab itu. Dan sekiranya tidak ada ketetapan yang terdahulu dari Tuhanmu, nescaya telah diputuskan di antara mereka. Dan sesungguhnya mereka benar-benar dalam keraguan yang mendalam tentangnya. 11:110; 41:45
- = Itu tidak sukar bagi Allah. 14:20; 35:17
- = "Maka apabila Aku telah menyempurnakan kejadiannya, dan Aku telah meniupkan roh (ciptaan)-Ku ke dalamnya, maka tunduklah kamu kepadanya dengan bersujud." 15:29; 38:72
- = Maka malaikat-malaikat itu semuanya bersujud. 15:30; 38:73
- = (Allah) berfirman: "Maka keluarlah daripadanya, kerana sesungguhnya kamu adalah orang yang terkutuk." 15:34; 38:77
- = (Iblis) berkata: "Ya Tuhanku, maka berilah aku tangguh hingga hari (manusia) dibangkitkan." 15:36; 38:79
- = (Allah) berfirman: "Maka sesungguhnya kamu termasuk orang-orang yang diberi tangguh." 15:37; 38:80
- = Hingga hari masa yang telah ditentukan." 15:38; 38:81
- = Kecuali hamba-hamba-Mu yang terpilih di antara mereka. 15:40; 38:83
- = Sesungguhnya orang-orang yang bertakwa berada di dalam taman-taman (syurga) dan mata air. 15:45; 51:15
- = (Ibrahim) berkata: "Apakah urusan kamu yang penting, wahai para rasul?" 15:57; 51:31
- = Mereka menjawab: "Kami diutus kepada kaum yang berdosa." 15:58; 51:32
- = Orang-orang yang beriman dan tidak mencampuradukkan iman mereka dengan kezaliman, mereka itulah yang mendapat keamanan dan mereka itu adalah orang-orang yang mendapat petunjuk. 16:42; 29:59
- = Sehingga mereka mengingkari nikmat yang telah Kami berikan kepada mereka. Maka bersenang-senanglah kamu, kelak kamu akan mengetahui (akibatnya). 16:55; 30:34
- = Kemudian dia menempuh suatu jalan (yang lain). 18:89; 18:92
- = Pergilah kepada Firaun, sesungguhnya dia telah melampaui batas. 20:24; 79:17
- = Dan orang-orang yang memelihara kemaluannya. 23:5; 70:29
- = Kecuali terhadap isteri-isteri mereka atau hamba sahaya yang mereka miliki, maka sesungguhnya mereka tidak tercela. 23:6; 70:30
- = Tetapi barangsiapa mencari di balik itu, maka mereka itulah orang-orang yang melampaui batas. 23:7; 70:31
- = Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya. 23:8; 70:32
- = (Nuh) berkata: "Ya Tuhanku, tolonglah aku kerana mereka telah mendustakan aku." 23:26; 23:39
